import assert from 'node:assert';
import { createState, frame, WIDTH, HEIGHT } from '../game/neon.js';

// Mock canvas context
const ctx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('Ball does not bounce off brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // Top-left brick

  // Position ball so it's about to hit the bottom face of the brick
  // Brick is at (offsetX, BRICK_TOP), width=72, height=20
  // Ball r=7.
  // To hit the bottom face from below: vy < 0 (moving up), y > brick.y + brick.h
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Slightly overlapping the bottom
  state.ball.vy = -100; // Moving UP
  state.ball.vx = 0;

  const vyBefore = state.ball.vy;

  frame(ctx, state);

  assert.strictEqual(state.ball.vy, vyBefore, 'Ball vy should have flipped but did not');
  assert.strictEqual(state.ball.vy < 0, true, 'Ball is still moving UP through the brick');
});

