const ctx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('Ball should bounce off the bottom face of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 1;
  state.ball.vy = -100;
  state.ball.vx = 0;

  frame(ctx, state);

  assert.strictEqual(state.ball.vy, 100, 'Ball vy should have flipped to positive (DOWN)');
});

test('Ball should bounce off the side face of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 1;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  frame(ctx, state);

  assert.strictEqual(state.ball.vx, -100, 'Ball vx should have flipped to negative (LEFT)');
});

test('Ball should not remain inside the brick after bounce (Anti-Sticky)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 1;
  state.ball.vy = -100;
  state.ball.vx = 0;

  frame(ctx, state);

  // The ball should be repositioned such that it no longer collides with the brick
  // Using a helper if needed, but here we can just re-use the logic
  const collides = (ball, brick) => (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );

  assert.strictEqual(collides(state.ball, brick), false, 'Ball should be pushed out of the brick');
});

test('Ball should bounce off the corner (both axes)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Hit bottom-right corner
  state.ball.x = brick.x + brick.w + 1;
  state.ball.y = brick.y + brick.h + 1;
  state.ball.vx = -100;
  state.ball.vy = -100;

  frame(ctx, state);

  assert.strictEqual(state.ball.vx, 100, 'Ball vx should flip on corner hit');
  assert.strictEqual(state.ball.vy, 100, 'Ball vy should flip on corner hit');
});

# Symptôme : la balle traverse les briques au lieu de rebondir

## D1 — Absence de rebond
- **Famille** : traversée / collant
- **Symptôme joueur** : la balle traverse les briques
- **Cause** : `game/neon.js:187` — la collision est détectée et la brique détruite, mais la vitesse de la balle n'est jamais modifiée.
- **Invariant violé** : tout contact avec une brique doit entraîner un changement de direction.
- **Déclencheur** : n'importe quelle collision balle/brique.
- **Attendu** : inversion de `vx` ou `vy` selon la face touchée.
- **Référence** : AABB Collision Response — inversion de la composante de vitesse normale à la face de collision.
- **Cas test** :
  ```js
  test('Ball should bounce off the bottom face of a brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + brick.h + 1;
    state.ball.vy = -100;
    state.ball.vx = 0;
    frame(ctx, state);
    assert.strictEqual(state.ball.vy, 100);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball vy should have flipped to positive (DOWN) -100 !== 100`
- **Discrimine** : une correction qui détruirait la brique sans changer la vitesse.
- **Vert quand** : la balle change de direction après l'impact.

## D2 — Recouvrement non résolu (Collant)
- **Famille** : collant
- **Symptôme joueur** : la balle peut vibrer ou rester coincée dans une brique
- **Cause** : `game/neon.js:187` — absence de repositionnement de la balle après le rebond.
- **Invariant violé** : après résolution, la balle doit être hors du rectangle de la brique.
- **Déclencheur** : collision avec pénétration > 0.
- **Attendu** : la position de la balle est ajustée pour être tangente à la brique.
- **Référence** : AABB Resolution — "push out" along the axis of least penetration.
- **Cas test** :
  ```js
  test('Ball should not remain inside the brick after bounce (Anti-Sticky)', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + brick.h + 1;
    state.ball.vy = -100;
    frame(ctx, state);
    assert.strictEqual(collides(state.ball, brick), false);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should be pushed out of the brick true !== false`
- **Discrimine** : une correction qui inverse la vitesse mais oublie de repositionner la balle.
- **Vert quand** : la balle ne chevauche plus la brique après le traitement de la collision.
- **Révélé par** : D1 (on ne remarque pas le manque de repositionnement tant que la balle traverse tout simplement).

## D3 — Mauvaise résolution des coins
- **Famille** : face vs coin
- **Symptôme joueur** : rebonds imprévisibles sur les angles des briques
- **Cause** : `game/neon.js:187` — absence de détection spécifique des coins.
- **Invariant violé** : un impact sur un coin doit inverser les deux composantes de vitesse.
- **Déclencheur** : collision où la pénétration sur X et Y est similaire.
- **Attendu** : `vx = -vx` ET `vy = -vy`.
- **Référence** : AABB Corner Resolution — flip both axes if collision is on a corner.
- **Cas test** :
  ```js
  test('Ball should bounce off the corner (both axes)', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w + 1;
    state.ball.y = brick.y + brick.h + 1;
    state.ball.vx = -100;
    state.ball.vy = -100;
    frame(ctx, state);
    assert.strictEqual(state.ball.vx, 100);
    assert.strictEqual(state.ball.vy, 100);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball vx should flip on corner hit -100 !== 100`
- **Discrimine** : une correction qui n'inverse qu'un seul axe même dans un coin.
- **Vert quand** : la balle repart dans la direction opposée sur les deux axes après un impact de coin.
- **Révélé par** : D1.

