import assert from 'node:assert/strict';
import test from 'node:test';
import { createState, frame } from './game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('Debug collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 1;
  state.ball.vy = -100;
  state.ball.vx = 0;

  console.log('Before frame:', { x: state.ball.x, y: state.ball.y, vx: state.ball.vx, vy: state.ball.vy });
  frame(mockCtx, state);
  console.log('After frame:', { x: state.ball.x, y: state.ball.y, vx: state.ball.vx, vy: state.ball.vy });

  assert.strictEqual(state.ball.vy, 100);
});

