edits.newText:
// Bricks: collision + bounce + score + drawing, all in one place.
let closestBrick = null;
let minPenetration = Infinity;

for (const brick of state.bricks) {
  if (!brick.alive) continue;

  if (collides(state.ball, brick)) {
    const dx = state.ball.x - (brick.x + brick.w / 2);
    const dy = state.ball.y - (brick.y + brick.h / 2);
    const px = brick.w / 2 + state.ball.r - Math.abs(dx);
    const py = brick.h / 2 + state.ball.r - Math.abs(dy);
    const penetration = Math.min(px, py);

    if (penetration < minPenetration) {
      minPenetration = penetration;
      closestBrick = brick;
    }
  }
}

if (closestBrick) {
  const brick = closestBrick;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  const dx = state.ball.x - (brick.x + brick.w / 2);
  const dy = state.ball.y - (brick.y + brick.h / 2);
  const px = brick.w / 2 + state.ball.r - Math.abs(dx);
  const py = brick.h / 2 + state.ball.r - Math.abs(dy);

  if (px < py) {
    state.ball.vx *= -1;
    state.ball.x += (dx > 0) ? px : -px;
  } else if (py < px) {
    state.ball.vy *= -1;
    state.ball.y += (dy > 0) ? py : -py;
  } else {
    state.ball.vx *= -1;
    state.ball.vy *= -1;
    state.ball.x += (dx > 0) ? px : -px;
    state.ball.y += (dy > 0) ? py : -py;
  }
}

for (const brick of state.bricks) {
  if (brick.alive) {
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }
}

